import numpy as np,itertools
A=np.array([[4,1,0,0,0],[4,6,1,1,1],[4,0,0,0,0],[4,0,0,0,0],[4,0,0,0,0]])
B=np.array([[4,4,4,4,4],[4,1,0,0,0],[4,6,0,0,0],[4,0,0,0,0],[4,0,0,0,0]])
O=np.array([[0,0,0,0,0],[6,2,2,2,2],[2,0,0,0,0],[2,0,0,0,0],[2,0,0,0,0]])
ops={'and':lambda a,b:(a&b),'or':lambda a,b:(a|b),'xor':lambda a,b:(a^b),'a-b':lambda a,b:a&~b,'b-a':lambda a,b:b&~a}
for i,j in itertools.product(range(4),repeat=2):
 a=np.rot90(A>0,i);b=np.rot90(B>0,j)
 for n,f in ops.items():
  x=f(a,b)
  if np.array_equal(x,O>0):print(i,j,n)
